const path = require('node:path');
const util = require('node:util');
const os = require('node:os');
const base = process.env.WORK_DIR || '/work';
const t = (name, f) => { try { console.log(name, String(f())); } catch (e) { console.log(name, 'ERR', e && e.message); } };
t('base', () => typeof base);
t('join1', () => path.join('/a', 'b', '../c', 'd.txt'));
t('join2', () => path.join(base, 'fsprobe').length > 0);
t('join3', () => path.join('/work', 'fsprobe'));
t('resolve', () => path.resolve('/x', 'y'));
t('basename', () => path.basename('/a/b.txt', '.txt'));
t('extname', () => path.extname('f.tar.gz'));
t('dirname', () => path.dirname('/a/b/c'));
t('normalize', () => path.normalize('/a//b/./c/..'));
t('isAbsolute', () => path.isAbsolute('a'));
t('parse', () => JSON.stringify(path.parse('/home/u/f.txt')));
t('relative', () => path.relative('/a/b', '/a/c/d'));
t('sep', () => path.sep);
t('url1', () => new URL('https://user:pw@example.com:8443/p/a/t/h?query=string&a=1#hash').host);
t('url2', () => new URL('../x?y=1', 'http://h.test/a/b/c').href);
t('sp', () => { const sp = new URLSearchParams('a=1&b=2&a=3'); sp.append('c', 'x y'); sp.delete('b'); return sp.getAll('a').join(',') + sp.toString() + sp.has('c'); });
t('inspect', () => util.inspect({ a: 1, b: [1, 2, { c: 3 }], s: 'str' }));
t('format', () => util.format('%s=%d %j', 'x', 5, { k: 1 }));
t('inspect2', () => util.inspect('q'));
t('types', () => util.types.isPromise(Promise.resolve()));
t('deepeq', () => util.isDeepStrictEqual({ a: [1] }, { a: [1] }));
t('os1', () => typeof os.hostname());
t('os2', () => os.EOL === '\n');
t('os3', () => typeof os.platform());
t('os4', () => typeof os.cpus().length);
t('os5', () => os.tmpdir().length > 0);
t('os6', () => typeof os.totalmem());
t('os7', () => typeof os.homedir());
